/// The low 64 bits of `a b`: the checked multiplier's steps replayed on `a` and `b`.
pub fn multiply64(c: &mut Builder, a: &[Wire; 64], b: &[Wire; 64]) -> [Wire; 64] {
    let wires = replay(c, a, b, &MULTIPLY64);
    MULTIPLY64_OUT.map(|operand| wires[operand as usize])
}

